/**
 * Re-emails the cleanup PDF to the recipients of a specific historical send (by id). Only successful past sends can be re-sent. The new attempt is logged as its own row in the send history with `trigger="manual"`. Does NOT bump the schedule's `lastSentAt`, so the next scheduled cron tick still fires on its normal cadence.
 * @summary Re-send a past cleanup-report email to its original recipients (admin only)
 */
export const ResendCleanupReportParams = zod.object({
  "id": zod.coerce.number().int()
})

export const resendCleanupReportBodyRecipientsMax = 50;

export const resendCleanupReportBodyAdditionalRecipientsMax = 50;



export const ResendCleanupReportBody = zod.object({
  "recipients": zod.array(zod.string()).max(resendCleanupReportBodyRecipientsMax).optional(),
  "additionalRecipients": zod.array(zod.string().email()).max(resendCleanupReportBodyAdditionalRecipientsMax).optional()
}).describe('Optional subset selector (task #201) and additional recipients list (task #210). When `recipients` is omitted or empty the email goes to every recipient of the original send (legacy behaviour). When provided, the email goes only to those addresses, which must all be present in the original send\'s recipient list. `additionalRecipients` (task #210) is a separate channel for forwarding the same historical PDF to addresses that were NOT in the original recipient list — e.g. a new hire who joined after the report ran. They are added on top of the resolved recipients/originals list, validated as emails, and audited distinctly.')

export const ResendCleanupReportResponse = zod.object({
  "ok": zod.boolean(),
  "sent": zod.boolean(),
  "recipients": zod.array(zod.string()).optional(),
  "rowCount": zod.number().int().optional(),
  "subset": zod.boolean().optional().describe('True when the send went to a strict subset of the original recipients (task #201).'),
  "additional": zod.number().int().optional().describe('Count of recipients that were NOT in the original recipient list (task #210) — i.e. the size of the `additionalRecipients` add-on after deduping against the original list.')
})


